import glob
import datetime as dt
from datetime import date, timedelta

ref = date(2025, 8, 12)
periods = {
    'today': [ref],
    'last_7_days': [ref - timedelta(days=i) for i in range(6, -1, -1)],
    'last_30_days': [ref - timedelta(days=i) for i in range(29, -1, -1)],
    'month_to_date': [date(ref.year, ref.month, 1) + timedelta(days=i) for i in range((ref - date(ref.year, ref.month, 1)).days + 1)],
}
counts = {period: {'ERROR': 0, 'WARNING': 0, 'INFO': 0} for period in periods}
grand = {'ERROR': 0, 'WARNING': 0, 'INFO': 0}

for path in sorted(glob.glob('/app/logs/*.log')):
    filename_date = date.fromisoformat(path.rsplit('/', 1)[-1].split('_', 1)[0])
    with open(path, encoding='utf-8') as fh:
        for line in fh:
            severity = line.split('[', 1)[1].split(']', 1)[0]
            if severity not in ('ERROR', 'WARNING', 'INFO'):
                continue
            grand[severity] += 1
            for period, dates in periods.items():
                if filename_date in dates:
                    counts[period][severity] += 1

with open('/app/summary.csv', 'w', encoding='utf-8') as fh:
    fh.write('period,severity,count\n')
    for period in ('today', 'last_7_days', 'last_30_days', 'month_to_date', 'total'):
        for severity in ('ERROR', 'WARNING', 'INFO'):
            value = grand[severity] if period == 'total' else counts[period][severity]
            fh.write(f'{period},{severity},{value}\n')

print('grand totals:', grand)
for period in ('today', 'last_7_days', 'last_30_days', 'month_to_date'):
    print(period, counts[period])
